mapper.select:
SELECT 
FROM wf_biz_process
WHERE deleted = 0
  AND biz_type = #{bizType}
  AND biz_id = #{bizId}
ORDER BY start_time ASC, id ASC

sql.where:
deleted = 0
AND starter_user_id = #{starterUserId}
AND (parent_instance_id IS NULL OR parent_instance_id = '')
AND biz_type = #{query.bizType}

    AND biz_title like concat('%', #{query.bizTitle}, '%')

mapper.select:
SELECT FROM ( SELECT , ROW_NUMBER() OVER ( PARTITION BY biz_type, biz_id ORDER BY start_time DESC, id DESC ) AS rn FROM wf_biz_process
) t WHERE t.rn = 1
AND t.status = #{query.status}
ORDER BY t.start_time DESC, t.id DESC LIMIT #{offset}, #{query.pageSize}

SELECT COUNT(1) FROM ( SELECT status, ROW_NUMBER() OVER ( PARTITION BY biz_type, biz_id ORDER BY start_time DESC, id DESC ) AS rn FROM wf_biz_process
) t WHERE t.rn = 1
AND t.status = #{query.status}

